-- A piece of garlic is a whole head at home, but recipes count cloves, and a
-- slice is not a piece of bread: those lines are weighed instead, keeping
-- what the cook counts in the note. A clove weighs about 5 g.
UPDATE `recipe_ingredients` SET `note` = CONCAT(FLOOR(`quantity`), IF(`quantity` = 1, ' diente', ' dientes')),
    `quantity` = `quantity` * 5, `unit` = 'GRAM'
    WHERE `ingredientId` = 'ing_ajo' AND `unit` = 'PIECE';
UPDATE `recipe_ingredients` SET `note` = '4 rebanadas', `quantity` = 120, `unit` = 'GRAM'
    WHERE `recipeId` = 'rec_tostadas_aguacate' AND `ingredientId` = 'ing_pan_integral';
